import 'dart:async';
import 'dart:convert';
import 'dart:js_interop';
import 'dart:typed_data';

import 'package:web/web.dart' as web;

import '../stores.dart';

SecretStore create() => WebSecretStore();

/// R251: secrets in the browser. Values are AES-256-GCM encrypted in localStorage with a key
/// generated by WebCrypto as **non-extractable** and kept in IndexedDB: page scripts can use it,
/// but its bytes can never be read out or copied with the localStorage data. Signing out clears
/// both. Device PINs are never written here (asked per page load).
class WebSecretStore implements SecretStore {
  static const _prefix = 'molaplan.s.';
  static const _db = 'molaplan-keys';
  static const _os = 'k';
  Future<web.CryptoKey>? _key;

  web.SubtleCrypto get _subtle => web.window.crypto.subtle;

  Future<T> _req<T extends JSAny?>(web.IDBRequest r) {
    final c = Completer<T>();
    r.onsuccess = (web.Event _) {
      c.complete(r.result as T);
    }.toJS;
    r.onerror = (web.Event _) {
      c.completeError(StateError('IndexedDB: ${r.error?.message}'));
    }.toJS;
    return c.future;
  }

  Future<web.IDBDatabase> _open() {
    final r = web.window.indexedDB.open(_db, 1);
    r.onupgradeneeded = (web.Event _) {
      final db = r.result as web.IDBDatabase;
      if (!db.objectStoreNames.contains(_os)) db.createObjectStore(_os);
    }.toJS;
    return _req<web.IDBDatabase>(r);
  }

  Future<web.CryptoKey> _loadKey() async {
    final db = await _open();
    try {
      final got = await _req<JSAny?>(db.transaction(_os.toJS, 'readonly').objectStore(_os).get('main'.toJS));
      if (got != null && got.isA<web.CryptoKey>()) return got as web.CryptoKey;
      final algo = {'name': 'AES-GCM', 'length': 256}.jsify() as JSObject;
      final key =
          await _subtle.generateKey(algo, false, ['encrypt', 'decrypt'].map((e) => e.toJS).toList().toJS).toDart
              as web.CryptoKey;
      await _req<JSAny?>(db.transaction(_os.toJS, 'readwrite').objectStore(_os).put(key, 'main'.toJS));
      return key;
    } finally {
      db.close();
    }
  }

  Future<web.CryptoKey> get _k => _key ??= _loadKey();

  @override
  Future<String?> read(String key) async {
    final raw = web.window.localStorage.getItem('$_prefix$key');
    if (raw == null) return null;
    try {
      final b = base64Decode(raw);
      final iv = b.sublist(0, 12), ct = b.sublist(12);
      final algo = {'name': 'AES-GCM', 'iv': iv.toJS}.jsify() as JSObject;
      final pt = await _subtle.decrypt(algo, await _k, ct.toJS).toDart as JSArrayBuffer;
      return utf8.decode(pt.toDart.asUint8List());
    } catch (_) {
      return null; // key lost (site data partly cleared): treat as missing
    }
  }

  @override
  Future<void> write(String key, String value) async {
    final iv = Uint8List(12);
    web.window.crypto.getRandomValues(iv.toJS);
    final algo = {'name': 'AES-GCM', 'iv': iv.toJS}.jsify() as JSObject;
    final ct = await _subtle.encrypt(algo, await _k, utf8.encode(value).toJS).toDart as JSArrayBuffer;
    web.window.localStorage.setItem('$_prefix$key', base64Encode([...iv, ...ct.toDart.asUint8List()]));
  }

  @override
  Future<void> delete(String key) async => web.window.localStorage.removeItem('$_prefix$key');

  /// Signing out on a browser: removes every stored secret and the key itself.
  static Future<void> wipe() async {
    final ls = web.window.localStorage;
    for (var i = ls.length - 1; i >= 0; i--) {
      final k = ls.key(i);
      if (k != null && k.startsWith(_prefix)) ls.removeItem(k);
    }
    web.window.indexedDB.deleteDatabase(_db);
  }
}
